211	// The lookup is read-only: it allocates no cursor, so a later commit receives
212	// the cursor it would have received without the queries, and it neither wakes
213	// a parked long poll nor a push subscriber.
214	func TestQueryChangesHTTPReadOnly(t *testing.T) {
215		h, s := newTestHandler(t)
216		registerDevice(t, h, "dev")
217		postRawChanges(t, h, "doc1", "dev", `[{"id":"a","payload":1}]`)
218	
219		// A parked long poll with a short wait must time out despite queries
220		// hitting the same document.
221		done := make(chan struct {
222			changes  int
223			timedOut bool
224			err      error
225		}, 1)
226		go func() {
227			changes, _, timedOut, err := s.WaitForChanges(t.Context(), "doc1", 1, 100, 250*time.Millisecond)
228			done <- struct {
229				changes  int
230				timedOut bool
231				err      error
232			}{len(changes), timedOut, err}
233		}()
234	
235		time.Sleep(30 * time.Millisecond) // let the poll park
236		for i := 0; i < 3; i++ {
237			if w := queryChanges(t, h, "doc1", `{"deviceId":"dev","ids":["a","missing"]}`); w.Code != http.StatusOK {
238				t.Fatalf("query %d = %d %s", i, w.Code, w.Body.String())
239			}
240		}
241	
242		got := <-done
243		if got.err != nil {
244			t.Fatalf("poll: %v", got.err)
245		}
246		if !got.timedOut || got.changes != 0 {
247			t.Fatalf("poll woken by a read-only query: %+v", got)
248		}
249	
250		// The queries consumed no cursor: the next commit gets cursor 2.
251		postRawChanges(t, h, "doc1", "dev", `[{"id":"b","payload":2}]`)
252		rows, next, err := s.ListChanges("doc1", 0, 100)
253		if err != nil {
254			t.Fatal(err)
255		}
256		if len(rows) != 2 || next != 2 || rows[1].Cursor != 2 {
257			t.Fatalf("query moved the cursor: rows=%+v next=%d", rows, next)
258		}
259	}
260	
261	// Method and path shape: only POST at the exact .../changes/query location is
262	// accepted; every other verb or shape is a JSON 400, never a redirect.
263	func TestQueryChangesHTTPMethodAndPath(t *testing.T) {
264		h, _ := newTestHandler(t)
265	
266		cases := []struct {
267			method string
268			path   string
269		}{
270			{http.MethodGet, "/v1/documents/doc1/changes/query"},
271			{http.MethodPut, "/v1/documents/doc1/changes/query"},
272			{http.MethodDelete, "/v1/documents/doc1/changes/query"},
273			{http.MethodPost, "/v1/documents/doc1/changes/query/"},
274			{http.MethodPost, "/v1/documents/doc1/changes/query/extra"},
275			{http.MethodPost, "/v1/documents/doc1/changes/queryextra"},
276			{http.MethodPost, "/v1/documents//changes/query"},
277			{http.MethodPost, "/v1/documents/doc1/changesx/query"},
278			// The batch lookup is document-level only; the same segment under a
279			// session change collection is not an endpoint there.
280			{http.MethodPost, "/v1/sessions/sess/documents/doc1/changes/query"},
281		}
282		for _, tc := range cases {
283			t.Run(tc.method+" "+tc.path, func(t *testing.T) {
284				r := httptest.NewRequest(tc.method, tc.path, strings.NewReader(`{"deviceId":"dev","ids":["a"]}`))
285				r.Header.Set("Content-Type", "application/json")
286				w := httptest.NewRecorder()
287				h.ServeHTTP(w, r)
288				if w.Code != http.StatusBadRequest {
289					t.Fatalf("status = %d want 400 body = %s", w.Code, w.Body.String())
290				}
291				if ct := w.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
292					t.Fatalf("content type = %q, want JSON", ct)
293				}
294				if loc := w.Header().Get("Location"); loc != "" {
295					t.Fatalf("failure redirected to %q", loc)
296				}
297			})
298		}
299	}
300	
301	// A document literally named "query" keeps its ordinary change routes; the
302	// query keyword is only recognized in the terminal subresource position.
303	func TestQueryChangesHTTPDocumentNamedQuery(t *testing.T) {
304		h, _ := newTestHandler(t)
305		registerDevice(t, h, "dev")
306		postRawChanges(t, h, "query", "dev", `[{"id":"z","payload":1}]`)
307	
308		// Ordinary paged read on the document named "query".
309		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/query/changes")
310		if w.Code != http.StatusOK || !strings.Contains(w.Body.String(), `"id":"z"`) {
311			t.Fatalf("paged read on doc named query = %d %s", w.Code, w.Body.String())
312		}
313		// The lookup subresource of that document answers normally too.
314		w = queryChanges(t, h, "query", `{"deviceId":"dev","ids":["z"]}`)
315		if w.Code != http.StatusOK || !strings.Contains(w.Body.String(), `"status":"found"`) {
316			t.Fatalf("query on doc named query = %d %s", w.Code, w.Body.String())
317		}
318	}
319	
320	// The query verdict derives solely from durable data: after a process
321	// restart the same request yields the byte-identical body, including found,
322	// missing and compacted answers.
323	func TestQueryChangesHTTPRestartStable(t *testing.T) {
324		dir := t.TempDir()
325		dbPath := filepath.Join(dir, "sync.db")
326	
327		st, err := app.Open(dbPath)
328		if err != nil {
329			t.Fatal(err)
330		}
331		h := NewHandler(st)
332		registerDevice(t, h, "dev-1")
333		postDocChanges(t, h, "doc", "dev-1", 3)
334		if w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}}); w.Code != http.StatusOK {
335			t.Fatal(w.Body.String())
336		}
337		if w := compactChanges(t, h, "doc", "dev-1"); w.Code != http.StatusOK {
338			t.Fatal(w.Body.String())
339		}
340		body := queryChanges(t, h, "doc", `{"deviceId":"dev-1","ids":["c1","c2","nope"]}`).Body.String()
341		if err := st.Close(); err != nil {
342			t.Fatal(err)
343		}
344	
345		st2, err := app.Open(dbPath)
346		if err != nil {
347			t.Fatal(err)
348		}
349		defer func() { _ = st2.Close() }()
350		h2 := NewHandler(st2)
351		r := httptest.NewRequest(http.MethodPost, "/v1/documents/doc/changes/query", strings.NewReader(`{"deviceId":"dev-1","ids":["c1","c2","nope"]}`))
352		r.Header.Set("Content-Type", "application/json")
353		w := httptest.NewRecorder()
354		h2.ServeHTTP(w, r)
355		if w.Code != http.StatusOK {
356			t.Fatalf("after restart = %d %s", w.Code, w.Body.String())
357		}
358		if w.Body.String() != body {
359			t.Fatalf("body changed across restart:\nbefore %q\nafter  %q", body, w.Body.String())
360		}
361	}
